EXTRA_TAGS = {
    "念のため": ["副詞", "N3"], "点呼する": ["動詞", "動詞・サ変", "N2"],
    "申込者": ["名詞", "N2"], "申し込み": ["名詞", "N3"], "苦労": ["名詞", "N3"],
    "確保": ["名詞", "N2"], "暮らし": ["名詞", "N3"], "存分": ["副詞", "N1"],
    "受け取る": ["動詞", "動詞・五段", "N3"], "テントを張る": ["動詞", "動詞・五段", "N3"],
    "程度のスペース": ["名詞", "N3"], "心とカラダ": ["名詞", "N4"],
    "心と体の健康": ["名詞", "N4"], "役立つ": ["動詞", "動詞・五段", "N3"],
    "行き来できる": ["動詞", "動詞・一段", "N3"], "カウンター": ["名詞", "N3"],
    "島の案内所": ["名詞", "N4"], "門出": ["名詞", "N1"],
    "仕舞う": ["動詞", "動詞・五段", "N3"], "平成": ["名詞", "N2"],
}

def write_card(c):
    theme, word = c["theme"], c["word"]
    data = {"Слово": word, "Чтение": c["reading"], "Перевод": c["translation"],
            "Подсказка": c["translation"].split(";")[0], "Пример": "<br>".join(c["examples"]),
            "Пример без слова": "<br>".join(c["blanks"]), "Пример перевод": "<br>".join(c["translations"]),
            "Картинка": "", "Произношение": "", "Заметки": c["notes"], "Кандзи-разбор": c["kanji"],
            "Показать фуригану": "Y", "Теги": [theme, *EXTRA_TAGS[word]]}
    folder = ROOT / "Карточки" / theme
    folder.mkdir(parents=True, exist_ok=True)
    path = folder / f"{word}.json"
    if path.exists():
        return
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n")
    word_list = ROOT / "Слова" / theme
    lines = set(word_list.read_text().splitlines()) if word_list.exists() else set()
    lines.add(word)
    word_list.write_text("\n".join(sorted(x.strip() for x in lines if x.strip())) + "\n")

for card in CARDS:
    write_card(card)

# Связанные файлы добавляются последующими этапами полного пайплайна.
for card in CARDS:
    path = ROOT / "Карточки" / card["theme"] / f"{card['word']}.json"
    data = json.loads(path.read_text())
    data["Теги"] = [card["theme"], *EXTRA_TAGS[card["word"]]]
    image = ROOT / "Картинки" / card["theme"] / f"{card['word']}.png"
    if image.is_file():
        data["Картинка"] = f'<img src="japanese_words_{card["word"]}.png">'
    audio_dir = ROOT / "Произношение" / card["theme"]
    audio = [audio_dir / f"{card['word']}_слово.mp3"] + [audio_dir / f"{card['word']}_пример_{i}.mp3" for i in range(1, 4)]
    if all(p.is_file() for p in audio):
        data["Произношение"] = "".join(f"[sound:{p.name}]" for p in audio)
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n")
